// Auto-generated 100% Guaranteed Inlined High-DPI Faculty Portraits
export const FACULTY_PHOTOS = {
  physics: "data:image/png;base64,",
  chemistry: "data:image/png;base64,",
  mathematics: "data:image/png;base64,",
  biology: "data:image/png;base64,"
};

if (typeof window !== 'undefined') {
  window.FACULTY_PHOTOS = FACULTY_PHOTOS;
  window.getFacultyPhoto = function(subjectOrPath) {
    if (!subjectOrPath) return FACULTY_PHOTOS.physics;
    const s = String(subjectOrPath).toLowerCase();
    if (s.includes('phys')) return FACULTY_PHOTOS.physics;
    if (s.includes('chem')) return FACULTY_PHOTOS.chemistry;
    if (s.includes('math')) return FACULTY_PHOTOS.mathematics;
    if (s.includes('bio')) return FACULTY_PHOTOS.biology;
    return FACULTY_PHOTOS.physics;
  };
}
